public partial class MainWindow {
 readonly CancellationTokenSource catalogCts=new();CancellationTokenSource? installCts;bool installing,updatingChoices,catalogLoading;string pickerMode="All",pickerQuery="";VersionEntry? selectedChoice;IReadOnlyList<RemoteVersion> remoteVersions=Array.Empty<RemoteVersion>();List<VersionEntry> choices=new();
 VersionEntry? SelectedChoice=>VersionCombo.SelectedItem as VersionEntry??selectedChoice;
 void UpdateChoices(string? prefer=null){var remote=remoteVersions.ToDictionary(v=>v.Id);choices=versions.Select(v=>v with{Remote=remote.GetValueOrDefault(v.Id)}).Concat(remoteVersions.Where(v=>v.Type is "release" or "snapshot"&&!versions.Any(local=>local.Id==v.Id)).Select(v=>new VersionEntry(v.Id,"Vanilla",v.Id,0){Installed=false,Remote=v})).ToList();
  selectedChoice=choices.FirstOrDefault(v=>v.Id==(prefer??selectedChoice?.Id)&&string.Equals(v.RootOverride,selectedChoice?.RootOverride,StringComparison.OrdinalIgnoreCase))??choices.FirstOrDefault(v=>v.Id==(prefer??selectedChoice?.Id))??choices.FirstOrDefault(v=>v.Installed&&v.Id=="1.21.1")??choices.FirstOrDefault();ApplyPickerFilter();UpdateLaunchButton();
 }
 void ApplyPickerFilter(){if(VersionCombo==null)return;foreach(var button in new[]{PickerAllTab,PickerInstalledTab,PickerRemoteTab,PickerForgeTab,PickerFabricTab})if(button!=null)button.Background=new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(settings.Theme=="brawl stars"?((string)button.Tag==pickerMode?"#715A9C":"#332941"):((string)button.Tag==pickerMode?"#3F593B":"#243139")));bool loaderTab=pickerMode is "Forge" or "Fabric";VersionCombo.Visibility=loaderTab?Visibility.Collapsed:Visibility.Visible;LoaderVersionList.IsEnabled=!quickCatalogLoading;LoaderVersionList.Visibility=loaderTab?Visibility.Visible:Visibility.Collapsed;SnapshotsBox.Visibility=loaderTab?Visibility.Collapsed:Visibility.Visible;if(loaderTab){var supported=quickLoaderVersions.GetValueOrDefault(pickerMode)??Array.Empty<string>();LoaderVersionList.ItemsSource=VersionCatalog.ForLoader(remoteVersions,versions,supported,pickerMode).Where(v=>pickerQuery.Length==0||v.Title.Contains(pickerQuery,StringComparison.OrdinalIgnoreCase)||v.BaseVersion.Contains(pickerQuery,StringComparison.OrdinalIgnoreCase)).ToList();CatalogStatus.Text=quickCatalogLoading?Loc.T("Проверяем поддерживаемые версии…"):quickCatalogError.Length>0?quickCatalogError:pickerMode+" · "+LoaderVersionList.Items.Count;}updatingChoices=true;try{var filtered=choices.Where(v=>(pickerMode!="Installed"||v.Installed)&&(pickerMode!="Remote"||!v.Installed)&&(v.Installed||SnapshotsBox.IsChecked==true||v.Remote?.Type=="release")&&(pickerQuery.Length==0||v.Title.Contains(pickerQuery,StringComparison.OrdinalIgnoreCase)||v.Loader.Contains(pickerQuery,StringComparison.OrdinalIgnoreCase))).ToList();VersionCombo.ItemsSource=filtered;VersionCombo.SelectedItem=filtered.FirstOrDefault(v=>selectedChoice!=null&&InstanceSelectionConverter.Same(v,selectedChoice));}finally{updatingChoices=false;}}
 void UpdateLaunchButton(){UpdateHero();var v=SelectedChoice;VersionPickerTitle.Text=v?.Title??Loc.T("Выбрать версию");PlayButton.IsEnabled=game is {HasExited:false}||v!=null&&!launching&&!installing;if(game is {HasExited:false})PlayButton.Content=Loc.T(Loc.T("ЗАКРЫТЬ ИГРУ  ■"));if(!launching&&!installing)PlayButton.Content=v is {Installed:false}?Loc.T("СКАЧАТЬ   ↓"):Loc.T("ИГРАТЬ   ▶");VersionPickerButton.IsEnabled=!installing&&!launching;}
 async Task LoadCatalogAsync(bool force=false){if(catalogLoading||remoteVersions.Count>0&&!force)return;catalogLoading=true;CatalogStatus.Text=Loc.T("Получение каталога Mojang…");try{using var service=new MojangInstaller();remoteVersions=await service.CatalogAsync(catalogCts.Token);UpdateChoices();CatalogStatus.Text=Loc.T($"Mojang · {remoteVersions.Count(v=>v.Type=="release")} релизов · поиск по номеру версии");}catch(OperationCanceledException){}catch(Exception e){CatalogStatus.Text=Loc.T("Нет связи с Mojang. Установленные версии доступны.");Log(Loc.T("Каталог: ")+e.Message);}finally{catalogLoading=false;}}
 async void VersionPickerOpen_Click(object sender,RoutedEventArgs e){if(installing||launching)return;if(VersionPopup.IsOpen){VersionPopup.IsOpen=false;return;}VersionPopup.IsOpen=true;await LoadCatalogAsync();if(VersionPopup.IsOpen)PickerSearch.Focus();}
 async void ReloadCatalog_Click(object sender,RoutedEventArgs e){await LoadCatalogAsync(true);if(pickerMode is "Forge" or "Fabric")await PrepareQuickLoaderAsync(pickerMode);ApplyPickerFilter();}
 void PickerSearch_Changed(object sender,TextChangedEventArgs e){pickerQuery=((TextBox)sender).Text.Trim();if(initialized)ApplyPickerFilter();}
 async void PickerTab_Click(object sender,RoutedEventArgs e){pickerMode=(string)((Button)sender).Tag;ApplyPickerFilter();if(pickerMode is "Forge" or "Fabric")await PrepareQuickLoaderAsync(pickerMode);ApplyPickerFilter();}
 async void LoaderVersion_Changed(object sender,SelectionChangedEventArgs e){if(LoaderVersionList.SelectedItem is not VersionEntry v)return;LoaderVersionList.SelectedItem=null;if(v.Installed){VersionCard_Click(new Button{Tag=v},new RoutedEventArgs());VersionPopup.IsOpen=false;return;}VersionPopup.IsOpen=false;await QuickInstallLoaderAsync(v.Loader,v.BaseVersion);}
 void PickerFilter_Changed(object sender,RoutedEventArgs e){if(initialized)ApplyPickerFilter();}
 static string Bytes(long n)=>n>=1024L*1024*1024?Loc.T($"{n/(1024d*1024*1024):0.00} ГБ"):Loc.T($"{n/(1024d*1024):0.0} МБ");
 void ShowDownloadProgress(InstallProgress p){DownloadTitle.Text=installing&&selectedChoice!=null?selectedChoice.Id+" · "+Loc.T(p.Stage):Loc.T(p.Stage);DownloadBar.Value=p.Total>0?p.Percent:0;DownloadPercent.Text=p.Total>0?$"{p.Percent:0}%":"";if(p.Total<=0){DownloadDetail.Text=Loc.T("Подготовка файлов · серверы Mojang");return;}string eta=p.Remaining is {} t?(t.TotalHours>=1?Loc.T($"~{(int)t.TotalHours} ч {t.Minutes} мин"):t.TotalMinutes>=1?Loc.T($"~{(int)t.TotalMinutes} мин {t.Seconds} с"):Loc.T($"~{Math.Max(1,t.Seconds)} с")):Loc.T("расчёт времени…");DownloadDetail.Text=Loc.T($"{Bytes(p.Done)} / {Bytes(p.Total)} · {Bytes((long)p.BytesPerSecond)}/с · осталось {eta} · файлов {p.Files}/{p.TotalFiles}");}
 async Task InstallChoiceAsync(VersionEntry v){if(installing||v.Remote==null)return;VersionPopup.IsOpen=false;installing=true;installCts=new();DownloadPanel.Visibility=Visibility.Visible;DownloadTitle.Text=Loc.T("Подготовка ")+v.Id;DownloadDetail.Text=Loc.T("Получение описания с серверов Mojang…");DownloadBar.Value=0;DownloadPercent.Text="";CancelDownloadButton.Content=Loc.T("Отмена");PlayButton.Content=Loc.T("ЗАГРУЗКА…");PlayButton.IsEnabled=false;VersionPickerButton.IsEnabled=false;VersionCombo.IsEnabled=false;Status(Loc.T("Скачивание ")+v.Id);var root=settings.GameRoot;var token=installCts.Token;
  try{using var service=new MojangInstaller();await service.InstallAsync(root,v.Remote,new Progress<InstallProgress>(ShowDownloadProgress),token);settings.Version=v.Id;await RefreshVersions();selectedChoice=choices.FirstOrDefault(c=>c.Id==v.Id);UpdateChoices(v.Id);DownloadTitle.Text=Loc.T("Установлено · Minecraft ")+v.Id;DownloadBar.Value=100;DownloadPercent.Text="100%";DownloadDetail.Text=Loc.T("Клиент, библиотеки, ресурсы и Java готовы. Можно играть офлайн.");Status("Minecraft "+v.Id+Loc.T(" установлен. Нажми «Играть»."));Log(Loc.T("Установка Mojang завершена: ")+v.Id);}
  catch(OperationCanceledException){DownloadTitle.Text=Loc.T("Загрузка отменена");DownloadDetail.Text=Loc.T("Скачанные файлы сохранены. Выбери эту версию, чтобы продолжить.");Status(Loc.T("Загрузка отменена. Повторная загрузка продолжит с сохранённых файлов."));}
  catch(Exception e){DownloadTitle.Text=Loc.T("Не удалось завершить загрузку");DownloadDetail.Text=e.Message;Status(Loc.T("Ошибка загрузки. Подробности в журнале."),true);Log(Loc.T("Загрузка: ")+e.Message);}
  finally{installCts.Dispose();installCts=null;installing=false;VersionCombo.IsEnabled=true;CancelDownloadButton.Content=Loc.T("Скрыть");UpdateLaunchButton();}
 }
 void CancelDownload_Click(object sender,RoutedEventArgs e){if(quickLoaderCts!=null){quickLoaderCts.Cancel();CancelDownloadButton.Content=Loc.T("Остановка…");}else if(modInstallCts!=null){modInstallCts.Cancel();CancelDownloadButton.Content=Loc.T("Остановка…");}else if(installCts!=null){installCts.Cancel();CancelDownloadButton.Content=Loc.T("Остановка…");}else DownloadPanel.Visibility=Visibility.Collapsed;}
